// Typical fridge/cupboard life once bought, by pantry category (days).
const SHELF_DAYS: Record<string, number> = {
  Seafood: 2,
  Meat: 3,
  Poultry: 2,
  Dairy: 7,
  Eggs: 21,
  Vegetables: 7,
  Fruits: 6,
  Bakery: 4,
  'Frozen Foods': 90,
  Beverages: 30,
  Snacks: 60,
  'Canned Foods': 365,
  'Pasta & Rice': 365,
  Grains: 180,
  Spices: 365,
  'Oils & Condiments': 180,
};

/** A sensible "use by" date for a fresh item, or null for long-lasting staples. */
function suggestedExpiry(category: string, from = new Date()): string | null {
  const days = SHELF_DAYS[category];
  if (!days || days > 60) return null;
  const d = new Date(from);
  d.setDate(d.getDate() + days);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

