/** Fallback by pantry category when the food itself isn't in the list. */
const CATEGORY_SAVE: Record<string, string> = {
  Vegetables: 'Cook it into a soup or a stew and freeze it: keeps 3 months.',
  Fruits: 'Cut it up and freeze it for smoothies, or cook it into a compote.',
  Meat: 'Cook it, or freeze it before the date: keeps 6 months frozen.',
  Poultry: 'Cook it today, or freeze it before the date: keeps 6 months frozen.',
  Seafood: 'Cook it today or freeze it: keeps 3 months frozen.',
  Dairy: 'Use it in cooking or baking today.',
  Bakery: 'Freeze it, or turn it into breadcrumbs.',
  Eggs: 'Beat and freeze in portions for baking: keeps 6 months.',
};

const DAYS_BY_PLACE: Record<string, KeepPlace> = { Vegetables: 'fridge', Fruits: 'fridge', Meat: 'fridge', Poultry: 'fridge', Seafood: 'fridge', Dairy: 'fridge', Eggs: 'fridge', Bakery: 'counter' };

/** How long this food usually keeps, where, and how to save it; null for long-lasting staples. */
const LONG_LASTING = /\b(stock|cubes?|powder(ed)?|sauces?|canned|tinned|cans?|dried|frozen|paste|seasoning|spices?|jerky|uht|long[- ]life|syrup|jam|pickled|flour|oil)\b/i;

function shelfLife(name: string, category?: string | null): ShelfLife | null {
  // Canned, dried, frozen and other long-lasting forms keep far longer than the fresh food.
  if (LONG_LASTING.test(name)) return null;
  const hit = FOODS.find((f) => f.re.test(name));
  if (hit) {
    const { re: _re, ...rest } = hit;
    return rest;
  }
  const days = category ? SHELF_DAYS[category] : undefined;
  if (!category || !days || days > 60) return null;
  return { food: category, days, place: DAYS_BY_PLACE[category] ?? 'fridge', save: CATEGORY_SAVE[category] ?? 'Use it in today’s cooking.' };
}

/** An estimated use-by date (YYYY-MM-DD) from the day it was added, or null for long-lasting staples. */
function estimateExpiry(name: string, category?: string | null, from: Date | string = new Date()): string | null {
  const life = shelfLife(name, category);
  if (!life || life.days > 90) return null;
  const d = typeof from === 'string' ? new Date(from) : new Date(from);
  d.setDate(d.getDate() + life.days);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

/** The date to go by: the one the family typed, or an estimate from when the food was added. */
function effectiveExpiry(item: { name: string; category?: string | null; expiration_date?: string | null; created_at?: string | null; tracking?: string | null }): { date: string | null; estimated: boolean } {
  // A date that matches the estimate from the day it was added was filled in by Firdam, not typed.
  if (item.expiration_date) return { date: item.expiration_date, estimated: !!item.created_at && item.expiration_date === estimateExpiry(item.name, item.category, item.created_at) };
  if (!item.created_at) return { date: null, estimated: false };
  const date = estimateExpiry(item.name, item.category, item.created_at);
  return { date, estimated: !!date };
}

/**
 * Whether a recipe ingredient is the same food as a pantry item, for "Recipes
 * with tomatoes": the shelf-life list knows the food's other names and plurals.
 */
function sameFood(pantryName: string, ingredient: string): boolean {
  const hit = FOODS.find((f) => f.re.test(pantryName));
  if (hit) return hit.re.test(ingredient) && !LONG_LASTING.test(ingredient);
  const stem = pantryName.toLowerCase().trim().replace(/(es|s)$/, '');
  return stem.length > 2 && ingredient.toLowerCase().includes(stem);
}

// ── inlined from supabase/functions/_shared/plan.ts ──
/**
 * Shared helpers for enforcing plan limits inside edge functions.
 * Uses the Supabase REST API with the service role (provided by Supabase).
 */

// Keep in sync with lib/plan/plan.ts. Each Companion message costs roughly
// $0.001–0.002 in OpenAI fees, an AI meal plan roughly $0.003–0.005.
const FREE_AI_PLANS_PER_MONTH = 2;
// The Companion chat is a paid feature; Free users get pantry matching (no AI) instead.
const FREE_COMPANION_MESSAGES_PER_MONTH = 0;
// Fair-use caps for paid plans, so one account can't run up a large bill.
// About two AI plans a week (a plan covers 3, 5 or 7 days); regenerating counts as a new plan.
const PAID_AI_PLANS_PER_MONTH = 8;
// Receipt scans (paid plans only): about $0.01 each in OpenAI fees.
const PAID_RECEIPT_SCANS_PER_MONTH = 30;
// Free plan: one receipt a month to try it.
const FREE_RECEIPT_SCANS_PER_MONTH = 1;
const PAID_COMPANION_MESSAGES_PER_DAY = 20;
// Swapping one meal with the AI chef (about $0.0005 each). Separate from whole
// AI plans so a swap never uses up a plan. Library swaps are always unlimited.
const FREE_AI_SWAPS_PER_MONTH = 10;
const PAID_AI_SWAPS_PER_MONTH = 40;

function env(name: string): string | undefined {
  const v = Deno.env.get(name);
  return v && v.trim() ? v.trim() : undefined;
}

interface AuthUser {
  id: string;
  email?: string;
}

async function getUser(req: Request): Promise<AuthUser | null> {
  const auth = req.headers.get("Authorization");
  const url = env("SUPABASE_URL");
  const anon = env("SUPABASE_ANON_KEY");
  if (!auth || !url || !anon) return null;
  const res = await fetch(`${url}/auth/v1/user`, { headers: { Authorization: auth, apikey: anon } });
  if (!res.ok) return null;
  return (await res.json()) as AuthUser;
}

function serviceHeaders(): Record<string, string> | null {
  const service = env("SUPABASE_SERVICE_ROLE_KEY");
  if (!service) return null;
  return { apikey: service, Authorization: `Bearer ${service}`, "Content-Type": "application/json" };
}

async function getPlan(userId: string): Promise<"free" | "premium" | "family"> {
  const url = env("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return "free";
  const res = await fetch(
    `${url}/rest/v1/subscriptions?user_id=eq.${encodeURIComponent(userId)}&select=plan,status,current_period_end`,
    { headers },
  );
  if (!res.ok) return "free";
  const rows = (await res.json()) as { plan: string; status: string; current_period_end: string | null }[];
  const sub = rows[0];
  if (!sub) return "free";
  const live = ["active", "trialing", "past_due"].includes(sub.status);
  const notExpired = !sub.current_period_end || new Date(sub.current_period_end) > new Date();
  if (!live || !notExpired) return "free";
  return sub.plan === "family" ? "family" : sub.plan === "premium" ? "premium" : "free";
}

function countUsageThisMonth(userId: string, kind: string): Promise<number> {
  const now = new Date();
  return countUsageSince(userId, kind, new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1)).toISOString());
}

/** Usage in the last 24 hours (a rolling "day" that ignores time zones). */
function countUsageToday(userId: string, kind: string): Promise<number> {
  return countUsageSince(userId, kind, new Date(Date.now() - 24 * 3600_000).toISOString());
}

async function countUsageSince(userId: string, kind: string, since: string): Promise<number> {
  const url = env("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return 0;
  const res = await fetch(
    `${url}/rest/v1/ai_usage?user_id=eq.${encodeURIComponent(userId)}&kind=eq.${encodeURIComponent(kind)}&created_at=gte.${encodeURIComponent(since)}&select=id`,
    { headers: { ...headers, Prefer: "count=exact", Range: "0-0" } },
  );
  const range = res.headers.get("content-range"); // e.g. "0-0/3" or "*/0"
  const total = range?.split("/")[1];
  return total && total !== "*" ? Number(total) : 0;
}

async function recordUsage(userId: string, kind: string): Promise<void> {
  const url = env("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return;
  await fetch(`${url}/rest/v1/ai_usage`, {
    method: "POST",
    headers: { ...headers, Prefer: "return=minimal" },
    body: JSON.stringify({ user_id: userId, kind }),
  });
}

/** True when the user is listed in `app_admins`. */
async function isAdminUser(userId: string): Promise<boolean> {
  const url = env("SUPABASE_URL");
  const headers = serviceHeaders();
  if (!url || !headers) return false;
  const res = await fetch(`${url}/rest/v1/app_admins?user_id=eq.${encodeURIComponent(userId)}&select=user_id`, {
    headers,
  });
  if (!res.ok) return false;
  return ((await res.json()) as unknown[]).length > 0;
}

// ── receipt-scan ──
/**
 * Reads a shopping receipt photo and returns the food items on it, ready for
 * the family to check before they go into the pantry. Free plan: 1 a month.
 *
 * POST { image: "data:image/jpeg;base64,…" }
 * → { items: [{ name, quantity, unit, category, staple }], store, date, total, currency, used, limit }
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, X-Client-Info, Apikey",
};
const MODEL = "gpt-4o-mini";
const MAX_IMAGE_CHARS = 6_000_000; // ~4.5 MB of base64

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { ...corsHeaders, "Content-Type": "application/json" } });
}

const CATEGORIES = [
  "Fruits", "Vegetables", "Meat", "Poultry", "Seafood", "Dairy", "Eggs", "Grains", "Pasta & Rice", "Canned Foods",
  "Frozen Foods", "Bakery", "Snacks", "Beverages", "Spices", "Oils & Condiments", "Other",
];
const UNITS = ["Pieces", "g", "kg", "ml", "L", "Pack", "Bottle", "Can", "Box"];

const PROMPT = `You read grocery receipts for a Muslim family's pantry app.
Return ONLY JSON: {"store": string|null, "date": "YYYY-MM-DD"|null, "total": number|null, "currency": string|null, "items": [...]}
Each item: {"name": string, "quantity": number, "unit": one of ${JSON.stringify(UNITS)}, "category": one of ${JSON.stringify(CATEGORIES)}, "staple": boolean}
Rules:
- Only things that are eaten or drunk. Skip everything else, even when a food word is in the name: appliances ("coffee machine", "kettle", "blender", "toaster"), cookware, dishes and kitchen tools, food containers, coffee filters, cleaning products, toiletries, medicine and vitamins, pet food, clothes, toys, electronics, stationery, flowers, bags, deposits, discounts, loyalty lines, totals and payment lines. When unsure whether a line is food, leave it out.
- "name": a short, plain English shopping-list name ("Chicken thighs", "Basmati rice", "Whole milk", "Tomatoes"), not the receipt's abbreviation or brand code. Expand abbreviations ("CHKN THGH" → "Chicken thighs").
- Quantity and unit from the line: weights (0.82 kg → 0.82 kg), sizes in the name (2L milk → 2 L; 500G → 500 g; 6PK / x6 → 6 Pieces), multiples (2 @ 1.99 → quantity 2). If unknown, quantity 1 and unit "Pack" (or "Pieces" for single fruit/veg items).
- Merge identical lines.
- "staple": true for long-lasting cupboard basics tracked by level (rice, flour, sugar, oil, ghee, lentils, pasta, couscous, bulgur, oats, tea, coffee, spices, salt, honey, tahini, tomato paste).
- If the image is not a receipt or is unreadable, return {"items": [], "store": null, "date": null, "total": null, "currency": null}.`;

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return new Response(null, { status: 200, headers: corsHeaders });
  if (req.method !== "POST") return json({ error: "Use POST." }, 405);
  try {
    const apiKey = Deno.env.get("OPENAI_API_KEY");
    if (!apiKey) return json({ error: "Receipt scanning isn't set up yet.", code: "not_configured" }, 501);

    const user = await getUser(req);
    if (!user) return json({ error: "Please sign in." }, 401);
    const plan = await getPlan(user.id);
    const limit = plan === "free" ? FREE_RECEIPT_SCANS_PER_MONTH : PAID_RECEIPT_SCANS_PER_MONTH;
    const used = await countUsageThisMonth(user.id, "receipt_scan");
    if (plan === "free" && used >= limit) {
      return json({ error: "You've used this month's free receipt scan. Quick add still works.", code: "limit_reached" }, 402);
    }
    if (used >= limit) {
      return json(
        { error: `You've scanned ${PAID_RECEIPT_SCANS_PER_MONTH} receipts this month — the monthly maximum. Quick add still works.`, code: "fair_use" },
        429,
      );
    }

    const body = (await req.json().catch(() => ({}))) as { image?: string };
    const image = typeof body.image === "string" ? body.image : "";
    if (!/^data:image\/(jpeg|jpg|png|webp);base64,/.test(image)) return json({ error: "Send a JPEG, PNG or WebP photo." }, 400);
    if (image.length > MAX_IMAGE_CHARS) return json({ error: "That photo is too large. Try again a little further away." }, 413);

    const res = await fetchOpenAI(apiKey, {
      model: MODEL,
      temperature: 0,
      max_tokens: 2500,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: PROMPT },
        {
          role: "user",
          content: [
            { type: "text", text: "Read this receipt." },
            { type: "image_url", image_url: { url: image, detail: "high" } },
          ],
        },
      ],
    });
    if (!res.ok) {
      const fail = await describeOpenAIFailure(res);
      return json({ error: fail.message, code: fail.code }, fail.status);
    }
    const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
    let parsed: Record<string, unknown> = {};
    try {
      parsed = JSON.parse(data.choices?.[0]?.message?.content ?? "{}");
    } catch {
      parsed = {};
    }
    const rawItems = Array.isArray(parsed.items) ? (parsed.items as Record<string, unknown>[]) : [];
    const items = rawItems
      .map((i) => {
        const name = typeof i.name === "string" ? i.name.trim().slice(0, 80) : "";
        const quantity = typeof i.quantity === "number" && i.quantity > 0 && i.quantity < 10000 ? i.quantity : 1;
        const unit = UNITS.includes(String(i.unit)) ? String(i.unit) : "Pack";
        const category = CATEGORIES.includes(String(i.category)) ? String(i.category) : "Other";
        return { name, quantity, unit, category, staple: i.staple === true };
      })
      // Kitchen only: soap, bags, batteries and the like are dropped.
      .filter((i) => i.name && !isNonFood(i.name))
      .slice(0, 80);
    // Halal only: haram lines on a receipt are not offered for the pantry.
    const skipped = items.filter((i) => haramItemReason(i.name)).map((i) => ({ name: i.name, reason: haramItemReason(i.name) }));
    const halalItems = items.filter((i) => !haramItemReason(i.name));

    // Count the scan once the receipt was read (a failed OpenAI call doesn't count).
    await recordUsage(user.id, "receipt_scan");

    const total = typeof parsed.total === "number" && parsed.total > 0 ? Math.round(parsed.total * 100) / 100 : null;
    const date = typeof parsed.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(parsed.date) ? parsed.date : null;
    return json({
      items: halalItems,
      skipped,
      store: typeof parsed.store === "string" ? parsed.store.slice(0, 80) : null,
      date,
      total,
      currency: typeof parsed.currency === "string" ? parsed.currency.slice(0, 8) : null,
      used: used + 1,
      limit,
    });
  } catch (err) {
    console.error(err);
    return json({ error: err instanceof Error ? err.message : "Unexpected error" }, 500);
  }
});
